      assert.equal(toRange(1, 1), '1');
      assert.equal(toRange(0, 1), '(?:0|1)');
      assert.equal(toRange(0, 2), '[0-2]');
      assert.equal(toRange(65666, 65667), '(?:65666|65667)');
